  static byte[] TestPng(int width=640,int height=260){var pixels=new byte[width*height*4];for(int y=0;y<height;y++)for(int x=0;x<width;x++){int p=(y*width+x)*4;bool sun=(x-495)*(x-495)+(y-65)*(y-65)<900;bool mountain=y>220-Math.Max(0,140-Math.Abs(x-225)*.65)&&y>100;byte r=(byte)(sun?239:mountain?65:195-y/5),g=(byte)(sun?197:mountain?107:221-y/8),b=(byte)(sun?110:mountain?92:216-y/9);pixels[p]=b;pixels[p+1]=g;pixels[p+2]=r;pixels[p+3]=255;}var bitmap=System.Windows.Media.Imaging.BitmapSource.Create(width,height,96,96,System.Windows.Media.PixelFormats.Bgra32,null,pixels,width*4);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var stream=new MemoryStream()){encoder.Save(stream);return stream.ToArray();}}
  static void ZipBytes(ZipArchive zip,string path,byte[] bytes){using(var s=zip.CreateEntry(path).Open())s.Write(bytes,0,bytes.Length);}
