  public static void Samples(string folder,StringBuilder log){foreach(string path in (File.Exists(folder)?new[]{folder}:Directory.GetFiles(folder)).Where(p=>Formats.Extensions.Contains(Path.GetExtension(p).ToLowerInvariant()))){var sw=Stopwatch.StartNew();var doc=Document.Read(path,"自动");if(doc.Blocks.Count<100||doc.Chapters.Count<1)throw new Exception("Sample lacks expected text or chapters: "+path);log.AppendLine(String.Format("SAMPLE: {0} | {1:N0} bytes | {2:N0} chars | {3:N0} paragraphs | {4:N0} chapters | {5:N0} ms",Path.GetFileName(path),new FileInfo(path).Length,doc.Characters,doc.Blocks.Count,doc.Chapters.Count,sw.ElapsedMilliseconds));}}
